package com.talentmatch.seeker;

import com.talentmatch.service.MatchReason;
import java.util.List;
import java.util.UUID;

/**
 * Response of {@code GET /api/candidates/{id}/matches} (§5.1).
 *
 * @param owner                 {@code candidateId} is the owner's candidate
 * @param profileVersion        the owner's current profile version; null for other candidates
 * @param recomputedJobs        scores written by this request
 * @param explanationsGenerated AI explanations generated by this request
 * @param unmatchableJobs       in-scope jobs without skills (not ranked)
 * @param reason                NO_MATCHABLE_JOBS / CANDIDATE_HAS_NO_SKILLS, or null
 * @param message               user-facing explanation of {@code reason}, or null
 */
public record CandidateMatchPageView(
        UUID candidateId,
        boolean owner,
        Integer profileVersion,
        Sort sort,
        int page,
        int limit,
        int totalPages,
        long totalElements,
        int recomputedJobs,
        int explanationsGenerated,
        long unmatchableJobs,
        MatchReason reason,
        String message,
        List<CandidateMatchView> matches) {
}
